// Resolve account + build platform-specific post request
const accounts = $input.first().json;
const account = Array.isArray(accounts) ? accounts[0] : accounts;
const body = $('Webhook').first().json.body;

if (!account || !account.access_token) {
  throw new Error(`No connected account found for id ${body.account_id}`);
}

const platform = account.platform;
const token = account.access_token;
const platformAccountId = account.account_id; // external ID (page ID, user URN, etc.)

// Build hashtag string
const hashtags = (body.hashtags || []).map(h => h.startsWith('#') ? h : `#${h}`).join(' ');
const fullContent = hashtags ? `${body.content}\n\n${hashtags}` : body.content;

let apiUrl = '';
let apiBody = {};
let apiMethod = 'POST';
let extraHeaders = {};

switch (platform) {
  case 'linkedin': {
    // LinkedIn UGC Post API
    apiUrl = 'https://api.linkedin.com/v2/ugcPosts';
    apiBody = {
      author: `urn:li:person:${platformAccountId}`,
      lifecycleState: 'PUBLISHED',
      specificContent: {
        'com.linkedin.ugc.ShareContent': {
          shareCommentary: { text: fullContent },
          shareMediaCategory: 'NONE'
        }
      },
      visibility: {
        'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC'
      }
    };
    extraHeaders = {
      'Authorization': `Bearer ${token}`,
      'X-Restli-Protocol-Version': '2.0.0'
    };
    break;
  }

  case 'facebook': {
    // Facebook Graph API — page post
    apiUrl = `https://graph.facebook.com/v18.0/${platformAccountId}/feed`;
    apiBody = {
      message: fullContent,
      access_token: token
    };
    break;
  }

  case 'instagram': {
    // Instagram Graph API — requires media_url for feed posts.
    // Step 1: create media container (caption only — works for Reels/Carousels with media_url)
    // For text-only we create a container via caption field.
    // Note: Instagram does NOT support text-only posts without media.
    // If no media_url provided, this will fail — the user must supply an image/video URL.
    const mediaUrl = body.media_url;
    if (!mediaUrl) {
      throw new Error('Instagram requires a media_url (image or video). Add one to the calendar item.');
    }
    apiUrl = `https://graph.facebook.com/v18.0/${platformAccountId}/media`;
    apiBody = {
      image_url: mediaUrl,
      caption: fullContent,
      access_token: token
    };
    break;
  }

  case 'x':
  case 'twitter': {
    // X (Twitter) API v2
    apiUrl = 'https://api.twitter.com/2/tweets';
    // Twitter has 280 char limit — truncate if needed
    const tweetText = fullContent.length > 280 ? fullContent.slice(0, 277) + '...' : fullContent;
    apiBody = { text: tweetText };
    extraHeaders = { 'Authorization': `Bearer ${token}` };
    break;
  }

  case 'tiktok': {
    // TikTok Content Posting API v2 — text post init
    apiUrl = 'https://open.tiktokapis.com/v2/post/publish/text/init/';
    apiBody = {
      post_info: {
        title: fullContent.slice(0, 150),
        privacy_level: 'PUBLIC_TO_EVERYONE',
        disable_duet: false,
        disable_comment: false,
        disable_stitch: false
      },
      source_info: { source: 'PULL_FROM_URL' }
    };
    extraHeaders = { 'Authorization': `Bearer ${token}` };
    break;
  }

  default:
    throw new Error(`Unsupported platform: ${platform}`);
}

return [{
  apiUrl,
  apiBody: JSON.stringify(apiBody),
  apiMethod,
  extraHeaders: JSON.stringify(extraHeaders),
  platform,
  run_id: body.run_id,
  org_id: body.org_id,
  content_piece_id: body.content_piece_id,
  calendar_item_id: body.calendar_item_id || null,
  callback_url: body.callback_url,
  account_id: body.account_id,
  // Instagram needs a second step to publish the container
  needs_instagram_publish: platform === 'instagram',
  instagram_account_id: platformAccountId,
  instagram_token: token
}];

// Instagram 2-step: publish the media container we just created
const prev = $input.first().json;
const buildData = $('Build Platform Request').first().json;

if (!buildData.needs_instagram_publish) {
  // Not Instagram — pass through
  return [{ ...prev, ...buildData, skipped: true }];
}

// The previous step created the container — get the container ID
const containerId = prev.id;
if (!containerId) throw new Error('Instagram media container creation failed');

const publishRes = await $helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v18.0/${buildData.instagram_account_id}/media_publish`,
  body: JSON.stringify({
    creation_id: containerId,
    access_token: buildData.instagram_token
  }),
  headers: { 'Content-Type': 'application/json' }
});

return [{ ...buildData, instagram_post_id: publishRes.id, skipped: false }];

// Update content_pieces status to 'published' in Supabase
const data = $('Build Platform Request').first().json;
const postResult = $input.first().json;

const supaUrl = process.env.SUPABASE_URL;
const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (data.content_piece_id && supaUrl && supaKey) {
  await $helpers.httpRequest({
    method: 'PATCH',
    url: `${supaUrl}/rest/v1/content_pieces?id=eq.${data.content_piece_id}`,
    headers: {
      'apikey': supaKey,
      'Authorization': `Bearer ${supaKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({ status: 'published' })
  });
}

// Update calendar item if linked
if (data.calendar_item_id && supaUrl && supaKey) {
  await $helpers.httpRequest({
    method: 'PATCH',
    url: `${supaUrl}/rest/v1/content_calendar?id=eq.${data.calendar_item_id}`,
    headers: {
      'apikey': supaKey,
      'Authorization': `Bearer ${supaKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({ status: 'published' })
  });
}

return [{ ...data, post_result: postResult }];

const crypto = require('crypto');
const data = $input.first().json;

const payload = {
  workflow_type: 'social_post',
  status: 'complete',
  run_id: data.run_id,
  org_id: data.org_id,
  platform: data.platform,
  account_id: data.account_id,
  content_piece_id: data.content_piece_id
};

const body = JSON.stringify(payload);
const secret = process.env.N8N_HMAC_SECRET || '';
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{ body, signature, callback_url: data.callback_url }];

const crypto = require('crypto');
const wb = $('Webhook').first().json.body;
const errMsg = $input.first().json.message || $input.first().json.error || 'Unknown error';

const payload = {
  workflow_type: 'social_post',
  status: 'failed',
  run_id: wb.run_id,
  org_id: wb.org_id,
  error_message: errMsg
};

const body = JSON.stringify(payload);
const secret = process.env.N8N_HMAC_SECRET || '';
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{ body, signature, callback_url: wb.callback_url }];
